        if v1-v0>0.08 and (d5 or 1)>0.3:
            side=-side; last_flip=now
            log({'flip':side,'d5':d5})
    if now-last_tx>3:
        wr('d0',f'PING x={x:.2f} y={y:.2f} d5={d5}'); last_tx=now
    if now-last_log>2:
        log({'st':st,'x':round(x,2),'y':round(y,2),'h':h,'d5':d5,'f':round(front,2),'sd':round(sd,2),'side':side,'d6':d6,'l':l}); last_log=now
    time.sleep(0.25)
finally:
  drive(0,0)
